-- First, let's check what sample data looks like in signals to understand ranges
SELECT signalregistry, snrratio, noisefloordbm, interflvl, rfistat, atmointerf 
FROM signals LIMIT 5;

-- Step 1: Add the analyzable flag column to the signals table
ALTER TABLE signals ADD COLUMN analyzable BOOLEAN;

-- Step 2: Create the trigger function that calculates quality indicator and sets the analyzable flag
CREATE OR REPLACE FUNCTION set_analyzable_flag()
RETURNS TRIGGER AS $$
DECLARE
    v_quality_indicator NUMERIC;
    v_falseposprob NUMERIC;
    v_sigunique NUMERIC;
    v_corrscore NUMERIC;
    v_anomscore NUMERIC;
    v_techsigprob NUMERIC;
    v_biosigprob NUMERIC;
    v_natsrcprob NUMERIC;
    v_artsrcprob NUMERIC;
    v_sigintegrity NUMERIC;
    v_tempstab NUMERIC;
    v_spatstab NUMERIC;
    v_freqstab NUMERIC;
    v_snrratio NUMERIC;
BEGIN
    -- Get signal probability data
    SELECT falseposprob, sigunique, corrscore, anomscore, techsigprob, biosigprob, natsrcprob, artsrcprob
    INTO v_falseposprob, v_sigunique, v_corrscore, v_anomscore, v_techsigprob, v_biosigprob, v_natsrcprob, v_artsrcprob
    FROM signalprobabilities WHERE signalref = NEW.signalregistry;

    -- Get signal dynamics data
    SELECT sigintegrity, tempstab, spatstab, freqstab
    INTO v_sigintegrity, v_tempstab, v_spatstab, v_freqstab
    FROM signaldynamics WHERE signalref = NEW.signalregistry;

    -- Calculate quality indicator based on multiple factors
    -- Quality indicator considers:
    -- - Low false positive probability (good)
    -- - High correlation score (good)
    -- - High anomaly score (potentially interesting)
    -- - Signal integrity from dynamics
    -- - SNR ratio from signals table
    -- - Temporal, spatial, frequency stability

    v_quality_indicator := COALESCE(v_sigintegrity, 50) 
        + COALESCE(v_tempstab * 100, 50) 
        + COALESCE(v_spatstab * 100, 50) 
        + COALESCE(v_freqstab * 100, 50)
        + COALESCE(v_corrscore * 100, 50)
        + GREATEST(COALESCE(v_snrratio, 0), 0);

    -- Set analyzable flag based on quality indicator threshold
    -- A signal is considered good enough if it has reasonable quality across dimensions
    IF v_quality_indicator >= 200 THEN
        NEW.analyzable := TRUE;
    ELSE
        NEW.analyzable := FALSE;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Step 3: Create the trigger to run automatically on INSERT or UPDATE
CREATE TRIGGER trg_set_analyzable_flag
BEFORE INSERT OR UPDATE ON signals
FOR EACH ROW
EXECUTE FUNCTION set_analyzable_flag();

ALTER TABLE signals ADD COLUMN analyzable BOOLEAN;

CREATE OR REPLACE FUNCTION set_analyzable_flag()
RETURNS TRIGGER AS $$
BEGIN
    NEW.analyzable := (NEW.snrratio - 0.1 * ABS(NEW.noisefloordbm)) > 0;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_set_analyzable_flag
BEFORE INSERT OR UPDATE ON signals
FOR EACH ROW
EXECUTE FUNCTION set_analyzable_flag();

ALTER TABLE signals ADD COLUMN analyzable BOOLEAN;

CREATE OR REPLACE FUNCTION set_analyzable_flag()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.snrratio IS NOT NULL AND NEW.noisefloordbm IS NOT NULL THEN
        NEW.analyzable := (NEW.snrratio - 0.1 * ABS(NEW.noisefloordbm)) > 0;
    ELSE
        NEW.analyzable := FALSE;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_set_analyzable_flag
BEFORE INSERT OR UPDATE ON signals
FOR EACH ROW
EXECUTE FUNCTION set_analyzable_flag();

ALTER TABLE signals ADD COLUMN IF NOT EXISTS analyzable BOOLEAN;

